from collections import deque

komsular = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"],
            "D": ["F"], "E": ["F"], "F": []}


def bfs(baslangic):
    kuyruk = deque([baslangic])
    gorulen = {baslangic}
    sira = []
    while kuyruk:
        dugum = kuyruk.popleft()
        sira.append(dugum)
        for k in komsular[dugum]:
            if k not in gorulen:
                gorulen.add(k)
                kuyruk.append(k)
    return sira


print(bfs("A"))
